        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G = load()

# Final hypothesis test:
# 1. Keep ALL input cells
# 2. Add X-diagonal from each corner OUTWARD

def predict_output(inp):
    h, w = len(inp), len(inp[0])

    # Find bbox
    bbox_r, bbox_c = [], []
    for r in range(h):
        for c in range(w):
            if inp[r][c] != 0:
                bbox_r.append(r)
                bbox_c.append(c)

    min_r, max_r = min(bbox_r), max(bbox_r)
    min_c, max_c = min(bbox_c), max(bbox_c)

    color = inp[min_r][min_c]
    result = [[0]*w for _ in range(h)]

    # Copy INPUT exactly first
    for r in range(h):
        for c in range(w):
            result[r][c] = inp[r][c]

    # Now draw diagonals FROM EACH CORNER GOING OUTWARD into the bbox interior
    directions = [(1,1),(1,-1),(-1,1),(-1,-1)]  # SE, SW, NE, NW

    for cr_start, cc_start in [(min_r,min_c),(min_r,max_c),(max_r,min_c),(max_r,max_c)]:
        for dr, dc in directions:
            rr, cc = cr_start, cc_start
            while 0 <= rr < h and 0 <= cc < w and (rr,cc) != (cr_start,cc_start):
                if result[rr][cc] == 0 or result[rr][cc] == color:
                    result[rr][cc] = color
                rr += dr
                cc += dc

    return result

